code.cpp:
class Solution {
public:
    int maxNonDecreasingLength(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        int dp0 = 1, dp1 = 1;
        int ans = 1;
        for (int i = 1; i < n; i++) {
            int ndp0 = 1, ndp1 = 1;
            if (nums1[i] >= nums1[i - 1]) ndp0 = max(ndp0, dp0 + 1);
            if (nums1[i] >= nums2[i - 1]) ndp0 = max(ndp0, dp1 + 1);
            if (nums2[i] >= nums1[i - 1]) ndp1 = max(ndp1, dp0 + 1);
            if (nums2[i] >= nums2[i - 1]) ndp1 = max(ndp1, dp1 + 1);
            dp0 = ndp0;
            dp1 = ndp1;
            ans = max(ans, max(dp0, dp1));
        }
        return ans;
    }
};
